import {doubleView,startDouble,selectDoubleConnector,selectDoubleParcel,predictDouble,restartDouble,supportDouble,stepDouble,doubleOutcome,doubleBasketLabel} from './willow-double-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yes=x=>x?'Yes':'No',label=(s,id)=>esc(doubleBasketLabel(s,id));
const button=(title,attrs='',kind='secondary')=>`<button type="button" class="${kind}" ${attrs}>${esc(title)}</button>`;
const findParcel=(s,id)=>s.parcels.find(p=>p.id===id);
const clues=s=>({stamp:s.clues.find(c=>c.feature==='stamp'),wrap:s.clues.find(c=>c.feature==='wrap')});
function art(p){const shape=p.stamp==='star'?'<path d="m60 22 9 18 21 3-15 14 4 21-19-10-19 10 4-21-15-14 21-3Z"/>':'<circle cx="60" cy="50" r="21"/>';return `<svg class="double-art" viewBox="0 0 120 94" role="img" aria-label="${esc(p.stamp)} stamp; ${esc(p.wrap)} wrap"><rect x="7" y="8" width="106" height="78" rx="10" fill="${p.wrap==='blue'?'#c8e1ed':'#f5df99'}" stroke="#183f39" stroke-width="3"/>${p.wrap==='blue'?'<path d="M19 14 49 80M46 14 76 80M73 14 103 80" stroke="#7faabe" stroke-width="5"/>':'<g fill="#c29443"><circle cx="28" cy="26" r="3"/><circle cx="47" cy="24" r="3"/><circle cx="91" cy="28" r="3"/><circle cx="22" cy="61" r="3"/><circle cx="91" cy="65" r="3"/></g>'}<circle cx="60" cy="50" r="29" fill="#fffef8" stroke="#183f39" stroke-width="3"/><g fill="#397958" stroke="#183f39" stroke-width="2">${shape}</g></svg>`;}
function ruleSentence(r){if(r.connector===null)return `Choose a connector. Then the rule can decide between the ${doubleBasketLabel(r.source,r.source.requestRule.then)} and ${doubleBasketLabel(r.source,r.source.requestRule.else)}.`;const {stamp,wrap}=clues(r.source);return `If this parcel has ${stamp.label} ${r.connector==='both'?'and':'or'} ${wrap.label}${r.connector==='one-or-both'?', including both':''}, send it to the ${doubleBasketLabel(r.source,r.source.requestRule.then)}; otherwise send it to the ${doubleBasketLabel(r.source,r.source.requestRule.else)}.`;}
function featureSummary(p){return `${p.stamp} stamp; ${p.wrap} wrap`;} // Both cues remain in text and art.
function spokenTrace(r,v){if(r.phase==='result'&&!v.resultAvailable)return 'This earlier result cannot be read here. Its raw final slot remains in notes. Start this trace again to continue.';const o=doubleOutcome(r.source,r.connector,r.selectedParcel);if(!o)return 'Choose a connector to read both clues.';const c=clues(r.source);let s=`${r.source.request} ${ruleSentence(r)} ${featureSummary(findParcel(r.source,r.selectedParcel))}.`;if(r.phase!=='ready')s+=` ${c.stamp.question} ${yes(o.stampYes)}.`;if(['wrap','combined','result'].includes(r.phase))s+=` ${c.wrap.question} ${yes(o.wrapYes)}.`;if(['combined','result'].includes(r.phase))s+=` Combined answer: ${yes(o.combinedYes)}. ${o.branch==='then'?'Then':'Otherwise'} branch.`;if(r.phase==='result')s+=` Your rule sent this parcel to ${doubleBasketLabel(r.source,o.actualBasket)}. Pip requested ${doubleBasketLabel(r.source,o.requestedBasket)}.`;return s;}
function traceText(r,v){
 const o=doubleOutcome(r.source,r.connector,r.selectedParcel),c=clues(r.source);
 if(!o)return '<p id="double-trace" tabindex="-1">Choose a connector on Rule and parcel before stepping.</p>';
 if(r.phase==='ready')return '<p id="double-trace" tabindex="-1">The machine is waiting. Read both clues before it chooses a branch.</p>';
 const stamp=`${c.stamp.question} ${yes(o.stampYes)}.`,wrap=`${c.wrap.question} ${yes(o.wrapYes)}.`;
 if(r.phase==='stamp')return `<div id="double-trace" tabindex="-1"><p>${esc(stamp)}</p><p>The wrap has not been read yet.</p></div>`;
 if(r.phase==='wrap')return `<div id="double-trace" tabindex="-1"><p>${esc(stamp)}</p><p>${esc(wrap)}</p><p>Both clues have been read. Combine their answers next.</p></div>`;
 const combined=r.connector==='both'?'Both asks for two Yes answers.':'At least one, including both, asks for one or two Yes answers.';
 const conclusion=`This parcel has ${yes(o.stampYes)} and ${yes(o.wrapYes)}, so the combined answer is ${yes(o.combinedYes)}.`;
 const branch=`${o.branch==='then'?'Then':'Otherwise'} is taken. The other branch does not run for this parcel.`;
 if(r.phase==='combined')return `<div id="double-trace" tabindex="-1"><p>${esc(stamp)} ${esc(wrap)}</p><p>${esc(combined)} ${esc(conclusion)}</p><p class="double-branch">${esc(branch)}</p></div>`;
 if(!v.resultAvailable)return '<div id="double-result" tabindex="-1" role="status"><p>This earlier result cannot be read here. Its raw final slot remains in notes. Start this trace again to continue.</p></div>';
 const source=v.result.source,result=v.result,clueCount=Number(result.stampYes)+Number(result.wrapYes),invitation=clueCount===2?source.text.bothClueInvite:clueCount===1?source.text.oneClueInvite:source.text.neitherClueInvite;
 return `<div id="double-result" class="double-result" tabindex="-1"><h2>One basket chosen</h2><p>${esc(stamp)} ${esc(wrap)} ${esc(combined)} ${esc(conclusion)}</p><p>${esc(branch)}</p><p>Your rule sent ${esc(findParcel(source,result.parcelId).title)} to <strong>${label(source,result.actualBasket)}</strong>. Pip's request calls for <strong>${label(source,result.requestedBasket)}</strong>.</p><p>${esc(result.matches?source.text.requestMatch:source.text.requestMismatch)}</p><p>${esc(invitation)}</p></div>`;
}
function history(v){const readable=v.readable.slice(-8),earlier=v.readable.length-readable.length;return `<details class="double-history"><summary>Recent runs (${v.readable.length} readable${v.unreadable.length?`, ${v.unreadable.length} unreadable`:''})</summary>${readable.map(({check:c})=>`<article><h3>Run ${c.id}: ${esc(findParcel(c.source,c.parcelId).title)}</h3><p>${c.connector==='both'?'Both clues':'At least one clue, including both'}. Stamp ${yes(c.stampYes)}; wrap ${yes(c.wrapYes)}; combined ${yes(c.combinedYes)}. ${c.branch==='then'?'Then':'Otherwise'} sent it to ${label(c.source,c.actualBasket)}. Pip requested ${label(c.source,c.requestedBasket)}.</p><p>Prediction before stepping: ${c.prediction==='unsure'?'not sure':c.prediction?label(c.source,c.prediction):'none'}. Help opened: ${c.support.helpOpened?'yes':'no'}. Worked together: ${c.support.together?'reported':'not reported'}.</p></article>`).join('')}${earlier?`<p>${earlier} older readable imported runs remain in the full notes download.</p>`:''}${v.unreadable.length?`<p>${v.unreadable.length} unreadable run slots remain raw in your notes.</p>`:''}${!v.readable.length&&!v.unreadable.length?'<p>No run has been saved yet.</p>':''}</details>`;}
const newDialog='<dialog class="double-new-dialog"><div class="dialog-content"><h2>Start a separate desk?</h2><p>The whole earlier desk, including unreadable slots and earlier recovery, will stay in your notes. Download notes first if you want another copy.</p><div class="double-actions"><button type="button" class="secondary" data-double-cancel-new>Keep this desk</button><button type="button" class="primary" data-double-confirm-new>Keep earlier desk and start</button></div></div></dialog>';
function evictDialog(v){const c=v.oldest?.check;return `<dialog class="double-evict-dialog"><div class="dialog-content"><h2>Make room for one run?</h2><p>Run ${c?.id??''}${c?`: ${esc(findParcel(c.source,c.parcelId).title)}`:''} is the oldest readable run. Sending this parcel will remove only that run from this desk. Unreadable records remain. <a href="#notes">Download notes first</a> if you want the older copy.</p><div class="double-actions"><button type="button" class="secondary" data-double-cancel-evict>Keep the earlier run</button><button type="button" class="primary" data-double-confirm-evict>Remove that run and send</button></div></div></dialog>`;}
export function doubleEntry(){return '<section class="double-entry"><h2>Willow Double Check</h2><p>Read two parcel clues. Change one connector to see why both and at least one can choose different baskets.</p><a class="secondary" href="#post/double-check">Try Willow Double Check</a></section>';}
export function doublePage(state,detail=''){
 const v=doubleView(state),head='<section class="double-desk" data-double-root><header><a class="back" href="#post">Back to Willow Post Office</a><p class="double-eyebrow">A tabletop rule machine</p><h1>Willow Double Check</h1></header>';
 if(v.status==='missing')return `${head}<p>Read two clues on four made-up parcels. Change a connector to see which basket one rule chooses. Your Post Office delivery stays waiting.</p>${button('Start a double check','data-double-start','primary')}<p id="double-status" role="status" tabindex="-1"></p></section>`;
 if(v.status==='recovery')return `${head}<h2>An earlier double check is kept</h2><p>This saved desk cannot be opened here. Its complete original record stays in Grown-up notes and the download.</p><p><a href="#notes">Grown-up notes and download</a></p>${button('Start a separate desk','data-double-new')}<p id="double-status" role="status" tabindex="-1"></p>${newDialog}</section>`;
 const r=v.root,p=findParcel(r.source,r.selectedParcel),page=detail==='trace'?'trace':'rule';
 const common=`<p class="double-intro">${esc(r.source.text.intro)}</p><div class="double-request"><strong>Request</strong><p>${esc(r.source.request)}</p><p class="double-selected">Selected: ${esc(p.title)} · ${esc(featureSummary(p))}</p></div><nav class="double-turns" aria-label="Desk turns"><a href="#post/double-check" ${page==='rule'?'aria-current="page"':''}>1. Rule and parcel</a><a href="#post/double-check/trace" ${page==='trace'?'aria-current="page"':''}>2. Trace</a></nav>`;
 const rule=`<section class="double-panel"><h2 id="double-rule-title" tabindex="-1">Choose a parcel</h2><div class="double-cards">${r.source.parcels.map(card=>`<button type="button" data-double-parcel="${esc(card.id)}" aria-pressed="${card.id===p.id}" class="double-card">${art(card)}<span>${esc(card.title)}</span><small>${esc(featureSummary(card))}</small></button>`).join('')}</div>${r.source.parcels.some(card=>card.stamp===r.source.clues.find(c=>c.feature==='stamp').value&&card.wrap!==r.source.clues.find(c=>c.feature==='wrap').value)?button('Try a one-clue parcel','data-double-contrast'):''}</section><section class="double-panel"><h2>Choose the connector</h2><fieldset class="double-choices"><legend>Which two-clue rule should the machine use?</legend><label><input type="radio" name="double-connector" value="both" data-double-connector ${r.connector==='both'?'checked':''}> Both clues</label><label><input type="radio" name="double-connector" value="one-or-both" data-double-connector ${r.connector==='one-or-both'?'checked':''}> At least one clue, including both</label></fieldset><p id="double-rule-sentence" tabindex="-1">${esc(ruleSentence(r))}</p><p>The machine follows your selected connector. Pip's request is a separate intention.</p><a class="primary" href="#post/double-check/trace">Go to trace</a></section>`;
 const prediction=r.phase==='ready'&&r.connector!==null?`<fieldset class="double-prediction"><legend>${esc(r.source.text.predictionPrompt)}</legend><div class="double-actions">${r.source.baskets.map(b=>button(b.label,`data-double-predict="${esc(b.id)}" aria-pressed="${r.prediction===b.id}"`)).join('')}${button('I am not sure yet',`data-double-predict="unsure" aria-pressed="${r.prediction==='unsure'}"`)}${button('Leave it blank','data-double-predict=""')}</div></fieldset>`:'';
 const stepLabel={ready:'Read the stamp',stamp:'Read the wrap',wrap:'Combine both clues',combined:'Send one parcel'}[r.phase];
 const currentStep={ready:0,stamp:1,wrap:2,combined:3,result:4}[r.phase],steps=['Stamp','Wrap','Combine','Basket'];
 const trace=`<section class="double-panel"><h2 id="double-trace-title" tabindex="-1">Read both clues</h2><div class="double-current">${art(p)}<p><strong>${esc(p.title)}</strong><br>${esc(featureSummary(p))}</p></div><ol class="double-steps">${steps.map((s,i)=>`<li class="${i<currentStep?'done':''} ${i===currentStep?'current':''}">${i+1} ${s}</li>`).join('')}</ol>${prediction}${traceText(r,v)}<div class="double-actions">${stepLabel?button(stepLabel,`data-double-step ${r.connector===null?'disabled':''}`,'primary'):''}${r.phase!=='ready'?button('Start this trace again','data-double-restart'):''}<a class="secondary" href="#post/double-check">Back to rule and parcel</a></div><p class="double-window-note">Eight recent readable runs stay here. Before an older run leaves this desk, you can download notes. Unreadable slots are never removed to make room.</p><details class="double-help" ${r.support.helpOpened?'open':''}><summary>Help if you like</summary>${button('Show an explanation','data-double-help')}${r.support.helpOpened?`<p id="double-help-text" tabindex="-1">${esc(r.source.text.help)}</p>`:''}${button('We worked together',`data-double-together aria-pressed="${r.support.together}"`)}${hearButton(spokenTrace(r,v),'Hear this visible trace')}</details></section>${history(v)}<details class="double-grown"><summary>For grown-ups</summary><p>These are supplied parcel and rule checks. A fitting route is not evidence of independent coding or mastery.</p><p>${esc(r.source.text.talk)}</p>${button('Start a separate desk','data-double-new')}</details><p><a href="#notes">Grown-up notes and download</a></p>${evictDialog(v)}`;
 return `${head}${common}${page==='rule'?rule:trace}${page==='rule'?`<div class="double-rule-help">${hearButton(`${r.source.request} ${ruleSentence(r)}`,'Hear this rule')}</div><details class="double-grown"><summary>For grown-ups</summary><p>These are supplied rule checks, not a score.</p>${button('Start a separate desk','data-double-new')}</details><p><a href="#notes">Grown-up notes and download</a></p>`:''}<p id="double-status" role="status" tabindex="-1"></p>${newDialog}</section>`;
}
export function doubleCheckNotes(state){if(!Object.hasOwn(state,'willowDoubleCheck'))return '';const v=doubleView(state),raw=JSON.stringify(state.willowDoubleCheck,null,2);return `<details class="panel"><summary>Willow Double Check: supplied connector practice</summary><p>${v.status==='recovery'?'This saved desk is unavailable here; its exact record remains below.':`${v.readable.length} readable runs, ${v.unreadable.length} unreadable raw slots. The current result is ${v.root.phase==='result'&&!v.resultAvailable?'unavailable':'readable or not yet sent'}.`} This is not independent coding or mastery.</p><pre>${esc(raw)}</pre></details>`;}
export function bindDoubleCheck(state,{save,render,navigate,focus,canExport,explorerId,isActive}={}){
 const root=document.querySelector('[data-double-root]');if(!root)return;
 const boundRoot=state.willowDoubleCheck,boundHash=location.hash,boundExplorer=explorerId?.();
 const live=()=>root.isConnected&&document.contains(root)&&location.hash===boundHash&&state.willowDoubleCheck===boundRoot&&explorerId?.()===boundExplorer&&(isActive?.()??true);
 const status=message=>{if(!live())return;const n=root.querySelector('#double-status');if(n){n.textContent=message;n.focus();}};
 const refusal='This action could not fit safely in your downloadable notes. Earlier work is unchanged. Download notes first or use a separate explorer.';
 const refresh=selector=>{save?.();render?.();focus?.(selector);};
 const attach=(selector,action,event='click')=>root.querySelectorAll(selector).forEach(el=>el.addEventListener(event,e=>{if(!live()||!el.isConnected){e.preventDefault();e.stopImmediatePropagation();return;}action(el,e);}));
 attach('[data-double-start]',()=>{if(!startDouble(state,canExport)){status(refusal);return;}save?.();if(location.hash==='#post/double-check/trace')navigate?.('#post/double-check');else {render?.();focus?.('#double-rule-title');}});
 attach('[data-double-connector]',el=>{if(selectDoubleConnector(state,el.value,canExport)){refresh('#double-rule-sentence');return;}const savedConnector=doubleView(state).root.connector;root.querySelectorAll('[data-double-connector]').forEach(input=>{input.checked=input.value===savedConnector;});status(refusal);},'change');
 attach('[data-double-parcel]',el=>selectDoubleParcel(state,el.dataset.doubleParcel,canExport)?refresh('#double-rule-title'):status(refusal));
 attach('[data-double-contrast]',()=>{const r=doubleView(state).root,stamp=r.source.clues.find(c=>c.feature==='stamp'),wrap=r.source.clues.find(c=>c.feature==='wrap'),p=r.source.parcels.find(x=>x.stamp===stamp.value&&x.wrap!==wrap.value);if(p)selectDoubleParcel(state,p.id,canExport)?refresh('#double-rule-title'):status(refusal);});
 attach('[data-double-predict]',el=>predictDouble(state,el.dataset.doublePredict||null,canExport)?refresh('#double-trace'):status(refusal));
 attach('[data-double-restart]',()=>restartDouble(state,canExport)?refresh('#double-trace'):status(refusal));
 attach('[data-double-help]',()=>supportDouble(state,'helpOpened',canExport)?refresh('#double-help-text'):status(refusal));
 attach('[data-double-together]',()=>supportDouble(state,'together',canExport)?refresh('[data-double-together]'):status(refusal));
 const evict=root.querySelector('.double-evict-dialog');
 attach('[data-double-step]',()=>{const v=doubleView(state);if(v.root.phase==='combined'&&v.needsEviction){evict?.showModal();return;}if(!stepDouble(state,canExport)){status(refusal);return;}refresh(v.root.phase==='combined'?'#double-result':'#double-trace');});
 attach('[data-double-cancel-evict]',()=>evict?.close());
 attach('[data-double-confirm-evict]',()=>{if(!evict?.open)return;evict.close();if(!stepDouble(state,canExport,true)){status(refusal);return;}refresh('#double-result');});
 const dialog=root.querySelector('.double-new-dialog');attach('[data-double-new]',()=>dialog?.showModal());attach('[data-double-cancel-new]',()=>dialog?.close());
 attach('[data-double-confirm-new]',()=>{if(!dialog?.open)return;dialog.close();if(!startDouble(state,canExport,true)){status(refusal);return;}save?.();if(location.hash==='#post/double-check/trace')navigate?.('#post/double-check');else {render?.();focus?.('#double-rule-title');}});
 root.querySelectorAll('a[href^="#"]').forEach(el=>el.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
 root.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',e=>{if(!live()){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
}
